"use client";
/* eslint-disable @next/next/no-img-element -- local preview images may be data URLs */

import Link from "next/link";
import { useRouter } from "next/navigation";
import { ChangeEvent, useEffect, useMemo, useState } from "react";
import { ArrowLeft, CalendarRange, Check, ChevronDown, ChevronUp, Eye, GripVertical, ImagePlus, Link2, MonitorDot, MoreHorizontal, Plus, RotateCcw, Save, Search, Trash2, Upload, X } from "lucide-react";
import { CurriculumLesson, CurriculumWeek, defaultCurriculum } from "../data";
import { defaultReviews, ManagedReview, REVIEWS_KEY } from "./site-live-content";
import { AdminCohort, AdminImage, BannerData, CohortStatus, CourseDraft, createAdminCohort, loadAdminBanner, loadAdminCohorts, loadPrimaryCourseAdmin, PixelData, saveAdminBanner, saveAdminCohort, saveCourseAdmin } from "@/lib/admin-content";

export { AdminProductsManager } from "./admin-products-manager";
export { AdminSettingsManager } from "./admin-settings-manager";

const CONTENT_EVENT = "brandyaction:content-updated";

function readStorage<T>(key:string,fallback:T):T{if(typeof window==="undefined")return fallback;try{return JSON.parse(window.localStorage.getItem(key)||"") as T}catch{return fallback}}
function saveStorage(key:string,value:unknown){window.localStorage.setItem(key,JSON.stringify(value));window.dispatchEvent(new Event(CONTENT_EVENT))}
function normalizeCurriculum(weeks:CurriculumWeek[]):CurriculumWeek[]{let day=0;return weeks.map(week=>({...week,lessons:week.lessons.filter(lesson=>String(lesson.kind)!=="LIVE").map(lesson=>{const kind:CurriculumLesson["kind"]=String(lesson.kind)==="자료"||String(lesson.kind)==="과제"?"자료":"VOD";day+=1;return {...lesson,day,kind,contentUrl:kind==="VOD"?lesson.contentUrl||"":undefined,resourceName:kind==="자료"?lesson.resourceName:undefined,resourceUrl:kind==="자료"?lesson.resourceUrl:undefined}})}))}

function Toast({show,children}:{show:boolean;children:React.ReactNode}){return <div className={`admin-toast ${show?"show":""}`}><Check/>{children}</div>}

export function LegacyAdminProductsManager(){
  const router=useRouter();
  const [editing,setEditing]=useState(false);
  const [tab,setTab]=useState("basic");
  const [course,setCourse]=useState<CourseDraft|null>(null);
  const [images,setImages]=useState<AdminImage[]>([]);
  const [pixels,setPixels]=useState<PixelData>({meta:"",kakao:"",google:"",enabled:true});
  const [saved,setSaved]=useState(false);
  const [saving,setSaving]=useState(false);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState("");
  const [resourceFiles,setResourceFiles]=useState<Map<string,File>>(new Map());
  const [curriculum,setCurriculum]=useState<CurriculumWeek[]>(defaultCurriculum);
  const [expandedWeeks,setExpandedWeeks]=useState<string[]>(defaultCurriculum.map(week=>week.id));
  useEffect(()=>{let active=true;loadPrimaryCourseAdmin().then(data=>{if(!active)return;setCourse(data.draft);setImages(data.images);setPixels(data.pixels);const next=normalizeCurriculum(data.curriculum.length?data.curriculum:defaultCurriculum);setCurriculum(next);setExpandedWeeks(next.map(week=>week.id));setLoading(false)}).catch(reason=>{if(!active)return;setError(reason instanceof Error?reason.message:"상품 정보를 불러오지 못했습니다.");setLoading(false)});return()=>{active=false}},[]);
  const confirmSave=async()=>{if(!course||saving)return;setSaving(true);setError("");try{await saveCourseAdmin({course,images,curriculum:normalizeCurriculum(curriculum),pixels,resourceFiles});const data=await loadPrimaryCourseAdmin();setCourse(data.draft);setImages(data.images);setCurriculum(normalizeCurriculum(data.curriculum));setResourceFiles(new Map());setSaved(true);router.refresh();window.setTimeout(()=>setSaved(false),1800)}catch(reason){setError(reason instanceof Error?reason.message:"저장 중 오류가 발생했습니다.")}finally{setSaving(false)}};
  const uploadImages=(event:ChangeEvent<HTMLInputElement>)=>{const files=Array.from(event.target.files||[]).slice(0,10-images.length).filter(file=>file.size<=1600000);setImages(current=>[...current,...files.map(file=>({file,url:URL.createObjectURL(file)}))].slice(0,10));event.target.value=""};
  const lessonCount=curriculum.reduce((sum,week)=>sum+week.lessons.length,0);
  const updateWeek=(weekId:string,key:"title"|"goal",value:string)=>setCurriculum(weeks=>weeks.map(week=>week.id===weekId?{...week,[key]:value}:week));
  const updateLesson=(weekId:string,lessonId:string,key:keyof CurriculumLesson,value:string|number)=>setCurriculum(weeks=>weeks.map(week=>week.id===weekId?{...week,lessons:week.lessons.map(lesson=>lesson.id===lessonId?{...lesson,[key]:value}:lesson)}:week));
  const addLesson=(weekId:string)=>setCurriculum(weeks=>{const nextDay=Math.max(0,...weeks.flatMap(week=>week.lessons.map(lesson=>lesson.day)))+1;return weeks.map(week=>week.id===weekId?{...week,lessons:[...week.lessons,{id:`day-${Date.now()}`,day:nextDay,title:"새 세부 커리큘럼",description:"학습 내용을 입력하세요.",kind:"VOD",duration:"20분",contentUrl:""}]}:week)});
  const changeLessonKind=(weekId:string,lessonId:string,kind:CurriculumLesson["kind"])=>setCurriculum(weeks=>weeks.map(week=>week.id===weekId?{...week,lessons:week.lessons.map(lesson=>lesson.id===lessonId?{...lesson,kind,contentUrl:kind==="VOD"?lesson.contentUrl||"":undefined,resourceName:kind==="자료"?lesson.resourceName:undefined,resourceUrl:kind==="자료"?lesson.resourceUrl:undefined}:lesson)}:week));
  const uploadLessonResource=(weekId:string,lessonId:string,event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;setCurriculum(weeks=>weeks.map(week=>week.id===weekId?{...week,lessons:week.lessons.map(lesson=>lesson.id===lessonId?{...lesson,resourceName:file.name,resourcePath:undefined}:lesson)}:week));setResourceFiles(current=>{const next=new Map(current);next.set(lessonId,file);return next});event.target.value=""};
  const removeLesson=(weekId:string,lessonId:string)=>setCurriculum(weeks=>weeks.map(week=>week.id===weekId?{...week,lessons:week.lessons.filter(lesson=>lesson.id!==lessonId)}:week));
  const addWeek=()=>{const index=curriculum.length+1;const id=`week-${Date.now()}`;setCurriculum(weeks=>[...weeks,{id,label:`${index}주차`,title:"새 주차",goal:"이번 주 완성 목표를 입력하세요",lessons:[]}]);setExpandedWeeks(value=>[...value,id])};
  const removeWeek=(weekId:string)=>setCurriculum(weeks=>weeks.filter(week=>week.id!==weekId));
  const toggleWeek=(weekId:string)=>setExpandedWeeks(value=>value.includes(weekId)?value.filter(id=>id!==weekId):[...value,weekId]);
  if(loading)return <section className="admin-panel admin-loading-state"><strong>상품 정보를 불러오는 중입니다.</strong></section>;
  if(!course)return <section className="admin-panel admin-loading-state"><strong>상품 정보를 불러오지 못했습니다.</strong><span>{error}</span></section>;
  if(!editing)return <>
    <div className="summary-chips"><span>전체 강의 <strong>1</strong></span><span>판매 중 <strong>1</strong></span><span>상세 이미지 <strong>{images.length||3}</strong></span><span>커리큘럼 <strong>{curriculum.length}주 · {lessonCount}일</strong></span></div>
    <section className="admin-panel product-overview-panel"><div className="admin-toolbar product-toolbar"><div><strong>등록 상품</strong><span>상품별 상세페이지·커리큘럼·픽셀을 한 곳에서 관리합니다.</span></div><button className="admin-primary" onClick={()=>setEditing(true)}><Save/> 상품 관리</button></div>
      <div className="product-management-row"><span className="product-name"><b className="product-thumb thumb-0">01</b><span><strong>{course.title}</strong><small>{course.instructorName} · VOD + {course.durationLabel} LIVE</small></span></span><div><small>판매 상태</small><span className={`status-label ${course.status==="published"?"success":"planned"}`}>{course.status==="published"?"판매 중":"판매 중지"}</span></div><div><small>상세페이지</small><strong>이미지 {images.length||3}장</strong></div><div><small>픽셀</small><span className="tracking-state"><i/> {pixels.enabled?"사용 중":"사용 안 함"}</span></div><div><small>커리큘럼</small><strong>{curriculum.length}주 · {lessonCount}일</strong></div><button className="manage-button prominent" onClick={()=>setEditing(true)}>상품 관리</button><button><MoreHorizontal/></button></div>
    </section>
    <section className="admin-panel admin-guide"><div><MonitorDot/><span><strong>상품 관리 구조</strong><small>기본 정보 → 이미지 상세페이지 → 커리큘럼 → 전환 픽셀 → 기수 연결</small></span></div><Link href="/classes/local-marketing"><Eye/> 고객 화면 미리보기</Link></section>
  </>;
  return <div className="admin-editor-wrap">
    <div className="editor-head"><button onClick={()=>setEditing(false)}><ArrowLeft/> 상품 목록</button><div><strong>{course.title}</strong><span className={`status-label ${course.status==="published"?"success":"planned"}`}>{course.status==="published"?"판매 중":"판매 중지"}</span></div><div><Link className="admin-outline" href={`/classes/${course.slug}`}><Eye/> 미리보기</Link><button className="admin-primary" onClick={confirmSave} disabled={saving}><Save/> {saving?"저장 중...":"저장"}</button></div></div>
    <div className="editor-tabs">{[["basic","기본 정보"],["detail","이미지 상세페이지"],["curriculum","커리큘럼"],["pixel","픽셀·전환 추적"]].map(([id,label])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{label}{id==="detail"&&<em>{images.length||3}</em>}</button>)}</div>
    {tab==="basic"&&<div className="editor-grid"><section className="admin-panel admin-form-card"><div className="form-card-head"><div><h2>상품 기본 정보</h2><p>클래스 목록과 상세 상단에 노출되는 정보입니다.</p></div><span className="completion-chip"><Check/> 실제 DB 연결</span></div><div className="admin-field-grid"><label className="field-full">상품명<input value={course.title} onChange={e=>setCourse({...course,title:e.target.value})}/></label><label>강사명<input value={course.instructorName} onChange={e=>setCourse({...course,instructorName:e.target.value})}/></label><label>기본 정가<input inputMode="numeric" value={course.listPrice} onChange={e=>setCourse({...course,listPrice:e.target.value})}/></label><label className="field-full">한 줄 소개<textarea value={course.summary} onChange={e=>setCourse({...course,summary:e.target.value})}/></label><label>진행 유형<select value="live" disabled><option value="live">VOD + 기수제 LIVE</option></select></label><label>판매 상태<select value={course.status} onChange={e=>setCourse({...course,status:e.target.value as CourseDraft["status"]})}><option value="published">판매 중</option><option value="draft">판매 중지</option><option value="archived">보관</option></select></label></div></section><aside className="admin-panel product-side-card"><span>노출 미리보기</span><div className="mini-product-preview"><b>01</b><small>{course.category||"마케팅"} · {course.durationLabel||"4주"} LIVE</small><strong>{course.title}</strong><em>연결 기수 기준</em></div><p>가격과 모집 상태는 연결된 기수 설정이 우선 적용됩니다.</p></aside></div>}
    {tab==="detail"&&<section className="admin-panel detail-image-editor"><div className="form-card-head"><div><h2>이미지형 상세페이지</h2><p>등록한 이미지가 위에서 아래 순서대로 고객 상세페이지에 이어 붙습니다.</p></div><span className="image-count">{images.length} / 10장</span></div><div className="detail-editor-grid"><label className="detail-dropzone"><input type="file" accept="image/png,image/jpeg,image/webp" multiple onChange={uploadImages}/><ImagePlus/><strong>상세 이미지를 업로드하세요</strong><span>여러 장 선택 가능 · JPG, PNG, WEBP · 장당 1.5MB</span><b>이미지 선택</b></label><div className="detail-image-guide"><strong>권장 제작 기준</strong><dl><div><dt>가로 크기</dt><dd>860px 이상</dd></div><div><dt>노출 방식</dt><dd>상하 여백 없이 연결</dd></div><div><dt>등록 순서</dt><dd>드래그로 변경</dd></div></dl><p>업로드 즉시 이 브라우저의 고객 상세 화면에서 확인할 수 있습니다.</p></div></div>
      <div className="uploaded-image-list">{images.length===0?<div className="empty-image-state"><span>기본 상세 이미지 3장이 고객 화면에 노출 중입니다.</span><small>이미지를 등록하면 기본 상세를 대체합니다.</small></div>:images.map((image,index)=><article key={`${image.id||image.url}-${index}`}><GripVertical/><img src={image.url} alt="등록 상세 미리보기"/><div><strong>상세 이미지 {String(index+1).padStart(2,"0")}</strong><small>860px 권장 · 저장 후 모든 고객에게 노출</small></div><button aria-label="이미지 삭제" onClick={()=>setImages(v=>v.filter((_,i)=>i!==index))}><Trash2/></button></article>)}</div>
    </section>}
    {tab==="curriculum"&&<section className="admin-panel curriculum-editor weekly-curriculum-editor">
      <div className="form-card-head"><div><h2>주차·일자별 커리큘럼</h2><p>Day별 콘텐츠를 VOD 또는 자료로 등록합니다.</p></div><button className="admin-primary" onClick={addWeek}><Plus/> 주차 추가</button></div>
      <div className="curriculum-summary-bar"><div><span>전체 구성</span><strong>{curriculum.length}주 · {lessonCount}일</strong></div><div><span>콘텐츠 형식</span><strong>VOD · 자료</strong></div><p>라이브 회차와 일정은 기수·회차 관리에서 별도로 설정합니다.</p></div>
      <div className="curriculum-week-list">{curriculum.map((week,weekIndex)=>{const expanded=expandedWeeks.includes(week.id);return <article className="curriculum-week-card" key={week.id}>
        <header><button className="week-drag" aria-label="주차 순서 변경"><GripVertical/></button><b>WEEK {String(weekIndex+1).padStart(2,"0")}</b><div><input aria-label={`${week.label} 제목`} value={week.title} onChange={e=>updateWeek(week.id,"title",e.target.value)}/><span>{week.lessons.length}개 세부 커리큘럼</span></div><input className="week-goal-input" aria-label={`${week.label} 완성 목표`} value={week.goal} onChange={e=>updateWeek(week.id,"goal",e.target.value)}/><button className="week-delete" aria-label="주차 삭제" onClick={()=>removeWeek(week.id)}><Trash2/></button><button className="week-toggle" aria-label={expanded?"주차 접기":"주차 펼치기"} onClick={()=>toggleWeek(week.id)}>{expanded?<ChevronUp/>:<ChevronDown/>}</button></header>
        {expanded&&<div className="week-lessons"><div className="lesson-editor-head"><span>일자</span><span>세부 커리큘럼</span><span>형식</span><span>콘텐츠 등록</span><span>분량</span><span/></div>{week.lessons.map(lesson=><div className="daily-curriculum-row" key={lesson.id}>
          <span className="day-sequence"><GripVertical/><b>Day {lesson.day}</b></span>
          <div className="daily-copy-fields"><input aria-label={`Day ${lesson.day} 제목`} value={lesson.title} onChange={e=>updateLesson(week.id,lesson.id,"title",e.target.value)}/><input aria-label={`Day ${lesson.day} 설명`} value={lesson.description} onChange={e=>updateLesson(week.id,lesson.id,"description",e.target.value)}/></div>
          <select aria-label={`Day ${lesson.day} 콘텐츠 형식`} value={lesson.kind} onChange={e=>changeLessonKind(week.id,lesson.id,e.target.value as CurriculumLesson["kind"])}><option>VOD</option><option>자료</option></select>
          {lesson.kind==="VOD"?<label className="lesson-link-field"><Link2/><input type="url" aria-label={`Day ${lesson.day} 영상 링크`} placeholder="YouTube·Vimeo 영상 링크" value={lesson.contentUrl||""} onChange={e=>updateLesson(week.id,lesson.id,"contentUrl",e.target.value)}/></label>:<label className={`lesson-file-field ${lesson.resourceName?"has-file":""}`}><input type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,image/*" onChange={e=>uploadLessonResource(week.id,lesson.id,e)}/><Upload/><span>{lesson.resourceName||"자료 파일 업로드"}</span></label>}
          <input aria-label={`Day ${lesson.day} 분량`} value={lesson.duration} onChange={e=>updateLesson(week.id,lesson.id,"duration",e.target.value)}/>
          <button aria-label="세부 커리큘럼 삭제" onClick={()=>removeLesson(week.id,lesson.id)}><Trash2/></button>
        </div>)}<button className="add-daily-row" onClick={()=>addLesson(week.id)}><Plus/> {week.label}에 Day 추가</button></div>}
      </article>})}</div>
    </section>}
    {tab==="pixel"&&<div className="editor-grid"><section className="admin-panel admin-form-card"><div className="form-card-head"><div><h2>상세페이지 픽셀 설정</h2><p>상품별 상세페이지 방문과 결제 전환을 광고 채널에 연결합니다.</p></div><label className="toggle-row"><input type="checkbox" checked={pixels.enabled} onChange={e=>setPixels({...pixels,enabled:e.target.checked})}/><span/></label></div><div className="pixel-fields"><label><span><b className="pixel-logo meta">M</b><span><strong>Meta Pixel</strong><small>상세 조회 · 결제 시작 · 구매 완료</small></span></span><input placeholder="Pixel ID 예: 1234567890" value={pixels.meta} onChange={e=>setPixels({...pixels,meta:e.target.value})}/></label><label><span><b className="pixel-logo kakao">K</b><span><strong>카카오 픽셀</strong><small>방문 · 장바구니 · 구매 이벤트</small></span></span><input placeholder="Track ID를 입력하세요" value={pixels.kakao} onChange={e=>setPixels({...pixels,kakao:e.target.value})}/></label><label><span><b className="pixel-logo google">G</b><span><strong>Google Analytics</strong><small>페이지뷰 · 결제 퍼널 이벤트</small></span></span><input placeholder="측정 ID 예: G-XXXXXXXX" value={pixels.google} onChange={e=>setPixels({...pixels,google:e.target.value})}/></label></div></section><aside className="admin-panel event-map"><span>자동 수집 이벤트</span>{[["01","ViewContent","상세페이지 진입"],["02","InitiateCheckout","결제 버튼 클릭"],["03","Purchase","결제 완료"]].map(row=><div key={row[0]}><b>{row[0]}</b><span><strong>{row[1]}</strong><small>{row[2]}</small></span><Check/></div>)}<p><Link2/> 상품마다 다른 픽셀 ID를 설정할 수 있습니다.</p></aside></div>}
    {error&&<p className="admin-save-error" role="alert">{error}</p>}<Toast show={saved}>상품 설정이 DB에 저장되었습니다.</Toast>
  </div>;
}

type CohortRow={name:string;period:string;people:string;session:string;status:string;note:string};
const initialCohortRows:CohortRow[]=[
  {name:"자영업 마케팅 실전반 · 1기",period:"08.19 — 09.09",people:"23 / 30명",session:"0 / 4",status:"모집 중",note:"D-16 · 잔여 7석"},
  {name:"자영업 마케팅 실전반 · 0기",period:"07.08 — 07.29",people:"30 / 30명",session:"4 / 4",status:"종료",note:"녹화본 무기한 제공 중"},
  {name:"자영업 마케팅 실전반 · 2기",period:"10.14 — 11.04",people:"0 / 30명",session:"0 / 4",status:"예정",note:"모집 일정 미설정"},
];
const cohortTone=(status:string)=>status==="모집 중"?"success":status==="종료"?"closed":"planned";
const shortDate=(value:string)=>value?value.slice(5).replace("-","."):"미정";

export function LegacyAdminCohortsManager(){
  const [rows,setRows]=useState<CohortRow[]>(initialCohortRows);
  const [selected,setSelected]=useState<number|null>(null);
  const [creating,setCreating]=useState(false);
  const [saved,setSaved]=useState(false);
  const [draft,setDraft]=useState({product:"자영업 마케팅 실전반",name:"3기",status:"예정",capacity:"30",listPrice:"490000",salePrice:"450000",recruitStart:"2026-08-03",recruitEnd:"2026-10-13",firstSession:"2026-10-14",sessionTime:"20:00",sessionCount:"4"});
  const sessionDates=useMemo(()=>Array.from({length:Number(draft.sessionCount)||0},(_,index)=>{const date=new Date(`${draft.firstSession}T12:00:00`);date.setDate(date.getDate()+index*7);return `${date.toLocaleDateString("ko-KR",{month:"2-digit",day:"2-digit",weekday:"short"})} ${draft.sessionTime}`}),[draft.firstSession,draft.sessionTime,draft.sessionCount]);
  const createCohort=()=>{const next:CohortRow={name:`${draft.product} · ${draft.name}`,period:`${shortDate(draft.firstSession)} — ${shortDate(new Date(new Date(`${draft.firstSession}T12:00:00`).getTime()+Math.max(0,Number(draft.sessionCount)-1)*7*86400000).toISOString().slice(0,10))}`,people:`0 / ${draft.capacity}명`,session:`0 / ${draft.sessionCount}`,status:draft.status,note:`모집 ${shortDate(draft.recruitStart)} — ${shortDate(draft.recruitEnd)}`};setRows(current=>[...current,next]);setCreating(false);setSelected(rows.length)};

  if(creating)return <div className="admin-editor-wrap cohort-create-wrap">
    <div className="editor-head"><button onClick={()=>setCreating(false)}><ArrowLeft/> 기수 목록</button><div><strong>새 기수 만들기</strong><span className="status-label planned">작성 중</span></div><div><button className="admin-outline" onClick={()=>setCreating(false)}>취소</button><button className="admin-primary" onClick={createCohort}><Check/> 기수 생성</button></div></div>
    <div className="cohort-create-steps"><span className="active"><b>1</b><em>기본·판매 정보</em></span><i/><span className="active"><b>2</b><em>모집·운영 일정</em></span><i/><span><b>3</b><em>생성 후 회차 관리</em></span></div>
    <div className="cohort-create-layout"><main>
      <section className="admin-panel admin-form-card cohort-create-section"><div className="form-card-head"><div><h2>기수 기본 정보</h2><p>어떤 상품의 몇 번째 기수인지 설정합니다.</p></div><span className="required-note">필수 항목</span></div><div className="admin-field-grid"><label className="field-full">연결 상품<select value={draft.product} onChange={e=>setDraft({...draft,product:e.target.value})}><option>자영업 마케팅 실전반</option></select></label><label>기수명<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="예: 3기"/></label><label>초기 상태<select value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value})}><option>예정</option><option>모집 중</option></select></label><label>모집 정원<input type="number" min="1" value={draft.capacity} onChange={e=>setDraft({...draft,capacity:e.target.value})}/></label><label>회차 수<select value={draft.sessionCount} onChange={e=>setDraft({...draft,sessionCount:e.target.value})}><option value="4">4회차</option><option value="6">6회차</option><option value="8">8회차</option></select></label></div></section>
      <section className="admin-panel admin-form-card cohort-create-section"><div className="form-card-head"><div><h2>가격·모집 기간</h2><p>상세페이지에 노출될 기수별 판매 조건입니다.</p></div></div><div className="admin-field-grid"><label>정가<input inputMode="numeric" value={draft.listPrice} onChange={e=>setDraft({...draft,listPrice:e.target.value})}/></label><label>판매가<input inputMode="numeric" value={draft.salePrice} onChange={e=>setDraft({...draft,salePrice:e.target.value})}/></label><label>모집 시작<input type="date" value={draft.recruitStart} onChange={e=>setDraft({...draft,recruitStart:e.target.value})}/></label><label>모집 마감<input type="date" value={draft.recruitEnd} onChange={e=>setDraft({...draft,recruitEnd:e.target.value})}/></label></div></section>
      <section className="admin-panel admin-form-card cohort-create-section"><div className="form-card-head"><div><h2>회차 일정 자동 생성</h2><p>첫 수업을 기준으로 매주 같은 요일·시간의 회차를 만듭니다.</p></div><span className="completion-chip"><Check/> 매주 반복</span></div><div className="admin-field-grid schedule-start-fields"><label>첫 수업일<input type="date" value={draft.firstSession} onChange={e=>setDraft({...draft,firstSession:e.target.value})}/></label><label>시작 시간<input type="time" value={draft.sessionTime} onChange={e=>setDraft({...draft,sessionTime:e.target.value})}/></label></div><div className="generated-session-list">{sessionDates.map((date,index)=><article key={`${date}-${index}`}><b>WEEK {String(index+1).padStart(2,"0")}</b><span>{date}</span><small>라이브 링크는 생성 후 입력</small></article>)}</div></section>
    </main><aside className="admin-panel cohort-create-summary"><span>생성 미리보기</span><strong>{draft.product}<br/>· {draft.name}</strong><dl><div><dt>상태</dt><dd>{draft.status}</dd></div><div><dt>모집</dt><dd>{shortDate(draft.recruitStart)} — {shortDate(draft.recruitEnd)}</dd></div><div><dt>정원</dt><dd>{draft.capacity}명</dd></div><div><dt>판매가</dt><dd>{Number(draft.salePrice||0).toLocaleString()}원</dd></div><div><dt>첫 수업</dt><dd>{shortDate(draft.firstSession)} {draft.sessionTime}</dd></div></dl><p>기수를 만든 뒤 각 회차의 Zoom 링크와 다시보기를 등록할 수 있습니다.</p><button className="admin-primary" onClick={createCohort}><Check/> 이 내용으로 기수 생성</button></aside></div>
  </div>;

  if(selected!==null){const cohort=rows[selected];return <div className="admin-editor-wrap"><div className="editor-head"><button onClick={()=>setSelected(null)}><ArrowLeft/> 기수 목록</button><div><strong>{cohort.name}</strong><span className={`status-label ${cohortTone(cohort.status)}`}>{cohort.status}</span></div><div><button className="admin-outline"><Eye/> 수강 홈 보기</button><button className="admin-primary" onClick={()=>{setSaved(true);window.setTimeout(()=>setSaved(false),1800)}}><Save/> 저장</button></div></div><div className="cohort-editor-grid"><section className="admin-panel admin-form-card"><div className="form-card-head"><div><h2>기수 판매·운영 정보</h2><p>모집 기간과 정원, 기수별 가격을 설정합니다.</p></div><span className="completion-chip"><Check/> {cohort.session.split("/")[1]?.trim()||"4"}회차 연결</span></div><div className="admin-field-grid"><label className="field-full">연결 상품<select><option>자영업 마케팅 실전반</option></select></label><label>기수명<input defaultValue={cohort.name.split("·").pop()?.trim()}/></label><label>정원<input defaultValue={cohort.people.split("/")[1]?.trim()||"30명"}/></label><label>정가<input defaultValue="490,000원"/></label><label>할인가<input defaultValue="450,000원"/></label><label>모집 시작<input type="date" defaultValue="2026-08-03"/></label><label>모집 마감<input type="date" defaultValue="2026-08-19"/></label></div></section><aside className="admin-panel cohort-summary-card"><span>모집 현황</span><strong>{cohort.people}</strong><i><em style={{width:selected===0?"77%":selected===1?"100%":"0%"}}/></i><dl><div><dt>결제 완료</dt><dd>{selected===0?"22명":selected===1?"30명":"0명"}</dd></div><div><dt>입금 대기</dt><dd>{selected===0?"1명":"0명"}</dd></div><div><dt>대기 신청</dt><dd>{selected===0?"14명":"0명"}</dd></div></dl></aside></div><section className="admin-panel cohort-session-editor"><div className="form-card-head"><div><h2>회차 운영</h2><p>기수별 날짜·라이브 링크·다시보기를 관리합니다.</p></div><button className="admin-outline"><Plus/> 회차 추가</button></div>{["고객 발견과 포지셔닝","매출 퍼널 설계","콘텐츠 전략과 제작","광고 운영과 최적화"].map((title,index)=><article key={title}><span><b>WEEK {index+1}</b><i className={selected===1?"done":index===0?"ready":""}/></span><div><strong>{title}</strong><small>{["우리 매장 고객 정의","매출 구조 맵","주간 콘텐츠 캘린더","30일 광고 테스트 플랜"][index]}</small></div><label>라이브 일시<input defaultValue={`${8+Math.floor(index/2)}.${19+index*7} (수) 20:00`}/></label><label>Zoom 링크<input placeholder="수업 전 입력"/></label><button><ChevronDown/></button></article>)}</section><Toast show={saved}>기수·회차 설정이 저장되었습니다.</Toast></div>}
  return <><div className="cohort-status-cards"><article><span>모집 중</span><strong>{rows.filter(row=>row.status==="모집 중").length}</strong><p>현재 신청 가능한 기수</p></article><article><span>진행 중</span><strong>0</strong><p>현재 라이브 진행 없음</p></article><article><span>예정</span><strong>{rows.filter(row=>row.status==="예정").length}</strong><p>오픈 전 운영 준비</p></article><article><span>대기 신청</span><strong>14</strong><p>정원 마감 시 전환</p></article></div><section className="admin-panel table-panel"><div className="admin-toolbar product-toolbar"><div><strong>기수별 운영 현황</strong><span>판매 조건과 각 회차 라이브·다시보기를 관리합니다.</span></div><button className="admin-primary" onClick={()=>setCreating(true)}><Plus/> 새 기수 만들기</button></div><div className="data-table cohort-table"><div className="data-head"><span>기수</span><span>운영 기간</span><span>신청 인원</span><span>회차</span><span>상태</span><span>운영</span><span/></div>{rows.map((r,i)=><div className="data-row" key={`${r.name}-${i}`}><span><strong>{r.name}</strong><small>{r.note}</small></span><span>{r.period}</span><span><b className="count-strong">{r.people}</b><i className="inline-progress"><em style={{width:i===0?"77%":i===1?"100%":"0%"}}/></i></span><span>{r.session}</span><span className={`status-label ${cohortTone(r.status)}`}>{r.status}</span><span><button className="manage-button prominent" onClick={()=>setSelected(i)}>관리하기</button></span><button><MoreHorizontal/></button></div>)}</div></section></>;
}

const statusLabel:Record<CohortStatus,string>={upcoming:"예정",recruiting:"모집 중",closed:"모집 마감",in_progress:"진행 중",completed:"종료",cancelled:"취소"};
const statusTone=(status:CohortStatus)=>status==="recruiting"||status==="in_progress"?"success":status==="completed"||status==="closed"?"closed":"planned";
const dateOnly=(value:string)=>value?new Intl.DateTimeFormat("ko-KR",{timeZone:"Asia/Seoul",month:"2-digit",day:"2-digit"}).format(new Date(value)).replace(/\.\s?/g,".").replace(/\.$/,""):"미정";
const dateInput=(value:string)=>value?new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Seoul",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date(value)):"";
const dateTimeInput=(value:string)=>{if(!value)return"";const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Seoul",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false}).formatToParts(new Date(value));const get=(type:string)=>parts.find(part=>part.type===type)?.value||"";return`${get("year")}-${get("month")}-${get("day")}T${get("hour")}:${get("minute")}`};
const seoulIso=(value:string)=>value&&!value.startsWith("T")?new Date(`${value}${value.length===10?"T00:00:00":""}+09:00`).toISOString():"";

export function AdminCohortsManager(){
  const router=useRouter();
  const [cohorts,setCohorts]=useState<AdminCohort[]>([]);
  const [courses,setCourses]=useState<Array<{id:string;courseCode:string;title:string;listPrice:number}>>([]);
  const [selectedId,setSelectedId]=useState<string|null>(null);
  const [creating,setCreating]=useState(false);
  const [loading,setLoading]=useState(true);
  const [saving,setSaving]=useState(false);
  const [saved,setSaved]=useState(false);
  const [error,setError]=useState("");
  const [draft,setDraft]=useState({courseId:"",name:"2기",status:"upcoming" as CohortStatus,capacity:"30",salePrice:"1490000",recruitStart:"2026-08-04",recruitEnd:"2026-08-18",operationStart:"2026-08-19",operationEnd:"2026-09-09",firstSession:"2026-08-19",sessionTime:"20:00",sessionCount:"4"});
  const refresh=async()=>{const data=await loadAdminCohorts();setCourses(data.courses);setCohorts(data.cohorts);setDraft(current=>({...current,courseId:current.courseId||data.courses[0]?.id||"",salePrice:current.salePrice||String(data.courses[0]?.listPrice||0)}));setLoading(false)};
  useEffect(()=>{let active=true;loadAdminCohorts().then(data=>{if(!active)return;setCourses(data.courses);setCohorts(data.cohorts);setDraft(current=>({...current,courseId:current.courseId||data.courses[0]?.id||"",salePrice:current.salePrice||String(data.courses[0]?.listPrice||0)}));setLoading(false)}).catch(reason=>{if(!active)return;setError(reason instanceof Error?reason.message:"기수 정보를 불러오지 못했습니다.");setLoading(false)});return()=>{active=false}},[]);
  const selected=cohorts.find(cohort=>cohort.id===selectedId)||null;
  const updateSelected=(patch:Partial<AdminCohort>)=>setCohorts(rows=>rows.map(row=>row.id===selectedId?{...row,...patch}:row));
  const updateSession=(sessionId:string,key:"title"|"expectedOutput"|"scheduledAt"|"liveUrl"|"replayUrl",value:string)=>setCohorts(rows=>rows.map(row=>row.id===selectedId?{...row,sessions:row.sessions.map(session=>session.id===sessionId?{...session,[key]:value}:session)}:row));
  const create=async()=>{const course=courses.find(item=>item.id===draft.courseId);if(!course||saving)return;setSaving(true);setError("");try{await createAdminCohort({course,name:draft.name,status:draft.status,capacity:Number(draft.capacity),price:Number(draft.salePrice),recruitmentStartAt:seoulIso(draft.recruitStart),recruitmentEndAt:seoulIso(draft.recruitEnd),operationStartAt:seoulIso(draft.operationStart),operationEndAt:seoulIso(`${draft.operationEnd}T23:59:59`),firstSessionAt:seoulIso(`${draft.firstSession}T${draft.sessionTime}:00`),sessionCount:Number(draft.sessionCount)});await refresh();setCreating(false);setSaved(true);router.refresh();window.setTimeout(()=>setSaved(false),1800)}catch(reason){setError(reason instanceof Error?reason.message:"기수를 생성하지 못했습니다.")}finally{setSaving(false)}};
  const save=async()=>{if(!selected||saving)return;setSaving(true);setError("");try{await saveAdminCohort(selected);await refresh();setSaved(true);router.refresh();window.setTimeout(()=>setSaved(false),1800)}catch(reason){setError(reason instanceof Error?reason.message:"기수·회차를 저장하지 못했습니다.")}finally{setSaving(false)}};
  const sessionDates=useMemo(()=>Array.from({length:Number(draft.sessionCount)||0},(_,index)=>{const date=new Date(`${draft.firstSession}T12:00:00+09:00`);date.setDate(date.getDate()+index*7);return`${dateOnly(date.toISOString())} ${draft.sessionTime}`}),[draft.firstSession,draft.sessionTime,draft.sessionCount]);

  if(loading)return<section className="admin-panel admin-loading-state"><strong>기수 정보를 불러오는 중입니다.</strong></section>;
  if(creating){const course=courses.find(item=>item.id===draft.courseId);return <div className="admin-editor-wrap cohort-create-wrap"><div className="editor-head"><button onClick={()=>setCreating(false)}><ArrowLeft/> 기수 목록</button><div><strong>새 기수 만들기</strong><span className="status-label planned">작성 중</span></div><div><button className="admin-outline" onClick={()=>setCreating(false)}>취소</button><button className="admin-primary" onClick={create} disabled={saving}><Check/> {saving?"생성 중...":"기수 생성"}</button></div></div><div className="cohort-create-layout"><main><section className="admin-panel admin-form-card cohort-create-section"><div className="form-card-head"><div><h2>기수 기본·판매 정보</h2><p>연결 상품, 모집 상태, 가격과 실제 운영기간을 설정합니다.</p></div><span className="required-note">실제 DB 생성</span></div><div className="admin-field-grid"><label className="field-full">연결 상품<select value={draft.courseId} onChange={e=>{const next=courses.find(item=>item.id===e.target.value);setDraft({...draft,courseId:e.target.value,salePrice:String(next?.listPrice||draft.salePrice)})}}>{courses.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label><label>기수명<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label>초기 상태<select value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value as CohortStatus})}><option value="upcoming">예정</option><option value="recruiting">모집 중</option></select></label><label>모집 정원<input type="number" min="1" value={draft.capacity} onChange={e=>setDraft({...draft,capacity:e.target.value})}/></label><label>판매가<input inputMode="numeric" value={draft.salePrice} onChange={e=>setDraft({...draft,salePrice:e.target.value})}/></label><label>모집 시작<input type="date" value={draft.recruitStart} onChange={e=>setDraft({...draft,recruitStart:e.target.value})}/></label><label>모집 마감<input type="date" value={draft.recruitEnd} onChange={e=>setDraft({...draft,recruitEnd:e.target.value})}/></label><label>운영 시작일<input type="date" value={draft.operationStart} onChange={e=>setDraft({...draft,operationStart:e.target.value})}/></label><label>운영 종료일<input type="date" value={draft.operationEnd} onChange={e=>setDraft({...draft,operationEnd:e.target.value})}/></label></div></section><section className="admin-panel admin-form-card cohort-create-section"><div className="form-card-head"><div><h2>라이브 회차 자동 생성</h2><p>첫 수업을 기준으로 매주 같은 요일과 시간에 생성합니다.</p></div></div><div className="admin-field-grid schedule-start-fields"><label>첫 수업일<input type="date" value={draft.firstSession} onChange={e=>setDraft({...draft,firstSession:e.target.value})}/></label><label>시작 시간<input type="time" value={draft.sessionTime} onChange={e=>setDraft({...draft,sessionTime:e.target.value})}/></label><label>회차 수<select value={draft.sessionCount} onChange={e=>setDraft({...draft,sessionCount:e.target.value})}><option value="4">4회차</option><option value="6">6회차</option><option value="8">8회차</option></select></label></div><div className="generated-session-list">{sessionDates.map((date,index)=><article key={date}><b>LIVE {index+1}</b><span>{date}</span><small>생성 후 링크 등록</small></article>)}</div></section>{error&&<p className="admin-save-error" role="alert">{error}</p>}</main><aside className="admin-panel cohort-create-summary"><span>생성 미리보기</span><strong>{course?.title}<br/>· {draft.name}</strong><dl><div><dt>상태</dt><dd>{statusLabel[draft.status]}</dd></div><div><dt>운영기간</dt><dd>{draft.operationStart}<br/>— {draft.operationEnd}</dd></div><div><dt>정원</dt><dd>{draft.capacity}명</dd></div><div><dt>판매가</dt><dd>{Number(draft.salePrice||0).toLocaleString()}원</dd></div><div><dt>회차</dt><dd>{draft.sessionCount}회</dd></div></dl><button className="admin-primary" onClick={create} disabled={saving}><Check/> 이 내용으로 생성</button></aside></div></div>}

  if(selected)return <div className="admin-editor-wrap"><div className="editor-head"><button onClick={()=>setSelectedId(null)}><ArrowLeft/> 기수 목록</button><div><strong>{selected.name}</strong><span className={`status-label ${statusTone(selected.status)}`}>{statusLabel[selected.status]}</span></div><div><button className="admin-primary" onClick={save} disabled={saving}><Save/> {saving?"저장 중...":"저장"}</button></div></div><div className="cohort-editor-grid"><section className="admin-panel admin-form-card"><div className="form-card-head"><div><h2>기수 판매·운영 정보</h2><p>모집 기간, 실제 운영기간, 정원, 가격과 상태를 설정합니다.</p></div><span className="completion-chip"><Check/> {selected.sessions.length}회차 연결</span></div><div className="admin-field-grid"><label className="field-full">연결 상품<input value={selected.courseTitle} disabled/></label><label>기수명<input value={selected.name} onChange={e=>updateSelected({name:e.target.value})}/></label><label>상태<select value={selected.status} onChange={e=>updateSelected({status:e.target.value as CohortStatus})}>{Object.entries(statusLabel).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>정원<input inputMode="numeric" value={selected.capacity} onChange={e=>updateSelected({capacity:e.target.value})}/></label><label>판매가<input inputMode="numeric" value={selected.price} onChange={e=>updateSelected({price:e.target.value})}/></label><label>모집 시작<input type="date" value={dateInput(selected.recruitmentStartAt)} onChange={e=>updateSelected({recruitmentStartAt:seoulIso(e.target.value)})}/></label><label>모집 마감<input type="date" value={dateInput(selected.recruitmentEndAt)} onChange={e=>updateSelected({recruitmentEndAt:seoulIso(e.target.value)})}/></label><label>운영 시작일<input type="date" value={dateInput(selected.operationStartAt)} onChange={e=>updateSelected({operationStartAt:seoulIso(e.target.value)})}/></label><label>운영 종료일<input type="date" value={dateInput(selected.operationEndAt)} onChange={e=>updateSelected({operationEndAt:seoulIso(`${e.target.value}T23:59:59`)})}/></label></div></section><aside className="admin-panel cohort-summary-card"><span>신청 현황</span><strong>{selected.enrolledCount} / {selected.capacity||"∞"}명</strong><i><em style={{width:`${Math.min(100,selected.capacity?selected.enrolledCount/Number(selected.capacity)*100:0)}%`}}/></i><dl><div><dt>운영기간</dt><dd>{dateOnly(selected.operationStartAt)} — {dateOnly(selected.operationEndAt)}</dd></div><div><dt>활성 수강권</dt><dd>{selected.enrolledCount}명</dd></div><div><dt>라이브 회차</dt><dd>{selected.sessions.length}회</dd></div></dl></aside></div><section className="admin-panel cohort-session-editor"><div className="form-card-head"><div><h2>회차 운영</h2><p>기수별 날짜·라이브 입장·다시보기 링크를 관리합니다.</p></div><span className="completion-chip"><Check/> 운영 회차 유지</span></div>{selected.sessions.map(session=><article key={session.id}><span><b>LIVE {session.sessionNumber}</b><i className={session.replayUrl?"done":session.liveUrl?"ready":""}/></span><div><input aria-label={`${session.sessionNumber}회차 제목`} value={session.title} onChange={e=>updateSession(session.id,"title",e.target.value)}/><small>{session.expectedOutput||"결과물을 입력하세요"}</small></div><label>라이브 일시<input type="datetime-local" value={dateTimeInput(session.scheduledAt)} onChange={e=>updateSession(session.id,"scheduledAt",seoulIso(e.target.value))}/></label><label>라이브 링크<input type="url" value={session.liveUrl} onChange={e=>updateSession(session.id,"liveUrl",e.target.value)} placeholder="Zoom·Meet URL"/></label><label>다시보기<input type="url" value={session.replayUrl} onChange={e=>updateSession(session.id,"replayUrl",e.target.value)} placeholder="Replay URL"/></label><button><ChevronDown/></button></article>)}{error&&<p className="admin-save-error" role="alert">{error}</p>}</section><Toast show={saved}>기수·운영기간·라이브 회차가 DB에 저장되었습니다.</Toast></div>;

  return <><div className="cohort-status-cards"><article><span>모집 중</span><strong>{cohorts.filter(row=>row.status==="recruiting").length}</strong><p>현재 신청 가능한 기수</p></article><article><span>진행 중</span><strong>{cohorts.filter(row=>row.status==="in_progress").length}</strong><p>현재 라이브 운영</p></article><article><span>예정</span><strong>{cohorts.filter(row=>row.status==="upcoming").length}</strong><p>오픈 전 운영 준비</p></article><article><span>전체 수강권</span><strong>{cohorts.reduce((sum,row)=>sum+row.enrolledCount,0)}</strong><p>활성 수강생 기준</p></article></div><section className="admin-panel table-panel"><div className="admin-toolbar product-toolbar"><div><strong>기수별 운영 현황</strong><span>판매 조건과 각 회차 라이브·다시보기를 실제 DB에서 관리합니다.</span></div><button className="admin-primary" onClick={()=>setCreating(true)}><Plus/> 새 기수 만들기</button></div><div className="data-table cohort-table"><div className="data-head"><span>기수</span><span>운영 기간</span><span>신청 인원</span><span>회차</span><span>상태</span><span>운영</span><span/></div>{cohorts.map(row=><div className="data-row" key={row.id}><span><strong>{row.name}</strong><small>{row.note||row.cohortCode}</small></span><span>{dateOnly(row.operationStartAt)} — {dateOnly(row.operationEndAt)}</span><span><b className="count-strong">{row.enrolledCount} / {row.capacity||"∞"}명</b><i className="inline-progress"><em style={{width:`${Math.min(100,row.capacity?row.enrolledCount/Number(row.capacity)*100:0)}%`}}/></i></span><span>{row.sessions.length}회</span><span className={`status-label ${statusTone(row.status)}`}>{statusLabel[row.status]}</span><span><button className="manage-button prominent" onClick={()=>setSelectedId(row.id)}>관리하기</button></span><button><MoreHorizontal/></button></div>)}</div>{error&&<p className="admin-save-error" role="alert">{error}</p>}</section><Toast show={saved}>기수가 DB에 생성되었습니다.</Toast></>;
}

