export function AdminOrdersManager(){
  const initial={start:"2026-08-01",end:"2026-08-31",field:"all",query:""};
  const [period,setPeriod]=useState("month");
  const [draft,setDraft]=useState(initial);
  const [applied,setApplied]=useState(initial);
  const setRange=(value:string,start:string,end:string)=>{setPeriod(value);setDraft(current=>({...current,start,end}))};
  const filtered=useMemo(()=>orderRows.filter(order=>{if(order.date<applied.start||order.date>applied.end)return false;const query=applied.query.trim().toLowerCase();if(!query)return true;const fieldMap:Record<string,string>={orderNo:order.orderNo,name:order.name,email:order.email,phone:order.phone,className:order.className};return applied.field==="all"?Object.values(fieldMap).some(value=>value.toLowerCase().includes(query)):(fieldMap[applied.field]||"").toLowerCase().includes(query)}),[applied]);
  const paidAmount=filtered.filter(order=>order.status==="결제 완료").reduce((sum,order)=>sum+order.amount,0);
  const refundAmount=filtered.filter(order=>order.status==="환불 완료").reduce((sum,order)=>sum+order.amount,0);
  const fieldLabel:Record<string,string>={all:"전체 조건",orderNo:"주문번호",name:"이름",email:"이메일",phone:"전화번호",className:"클래스"};
  const reset=()=>{setPeriod("month");setDraft(initial);setApplied(initial)};
  return <>
    <section className="admin-panel order-search-panel"><div className="order-search-title"><div><CalendarRange/><span><strong>결제 조회 조건</strong><small>기간과 고객·주문 상세 조건을 조합해 검색합니다.</small></span></div><button onClick={reset}><RotateCcw/> 조건 초기화</button></div><div className="order-filter-row"><b>조회기간</b><div className="period-buttons"><button className={period==="today"?"active":""} onClick={()=>setRange("today","2026-08-03","2026-08-03")}>오늘</button><button className={period==="week"?"active":""} onClick={()=>setRange("week","2026-07-28","2026-08-03")}>1주일</button><button className={period==="month"?"active":""} onClick={()=>setRange("month","2026-08-01","2026-08-31")}>이번 달</button><button className={period==="quarter"?"active":""} onClick={()=>setRange("quarter","2026-05-03","2026-08-03")}>3개월</button></div><div className="date-range-inputs"><input aria-label="조회 시작일" type="date" value={draft.start} onChange={e=>{setPeriod("custom");setDraft({...draft,start:e.target.value})}}/><span>—</span><input aria-label="조회 종료일" type="date" value={draft.end} onChange={e=>{setPeriod("custom");setDraft({...draft,end:e.target.value})}}/></div></div><div className="order-filter-row detail-filter-row"><b>상세 조건</b><select aria-label="상세 검색 조건" value={draft.field} onChange={e=>setDraft({...draft,field:e.target.value})}>{Object.entries(fieldLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><div className="detail-search-box"><Search/><input value={draft.query} onChange={e=>setDraft({...draft,query:e.target.value})} onKeyDown={e=>{if(e.key==="Enter")setApplied(draft)}} placeholder={`${fieldLabel[draft.field]}로 검색`}/></div><button className="admin-primary" onClick={()=>setApplied(draft)}><Search/> 검색</button></div></section>
    <section className="order-metrics filtered-order-metrics"><article><span>검색 결과</span><strong>{filtered.length}건</strong><small>{draft.start} — {draft.end}</small></article><article><span>결제 완료 금액</span><strong>{paidAmount.toLocaleString()}원</strong><small>입금 대기 제외</small></article><article><span>환불 금액</span><strong>{refundAmount.toLocaleString()}원</strong><small>환불 완료 기준</small></article><article><span>결제 완료</span><strong>{filtered.filter(order=>order.status==="결제 완료").length}건</strong><small>검색 결과 내 집계</small></article></section>
    <section className="admin-panel table-panel order-results-panel"><div className="order-result-head"><div><strong>결제 내역</strong><span>총 {filtered.length}건의 주문</span></div><button className="admin-outline">엑셀 다운로드</button></div><div className="data-table order-query-table"><div className="data-head"><span>주문번호·일자</span><span>주문자</span><span>클래스</span><span>결제 금액</span><span>결제 수단</span><span>상태</span><span/></div>{filtered.length===0?<div className="order-empty-state"><Search/><strong>조건에 맞는 결제 내역이 없습니다.</strong><span>조회기간이나 상세 검색어를 바꿔보세요.</span></div>:filtered.map(order=><div className="data-row" key={order.orderNo}><span className="order-id-cell"><strong>{order.orderNo}</strong><small>{order.date}</small></span><span className="order-customer-cell"><strong>{order.name}</strong><small>{order.email}</small><small>{order.phone}</small></span><span>{order.className}</span><strong>{order.amount.toLocaleString()}원</strong><span>{order.method}</span><span className={`status-label ${order.status==="환불 완료"?"refund":order.status==="입금 대기"?"planned":"success"}`}>{order.status}</span><button aria-label={`${order.name} 주문 상세`}><MoreHorizontal/></button></div>)}</div></section>
  </>;
}

export function AdminReviewsManager(){
  const [reviews,setReviews]=useState<ManagedReview[]>(defaultReviews);
  const [tab,setTab]=useState<"all"|"featured">("all");
  const [query,setQuery]=useState("");
  useEffect(()=>{const timer=window.setTimeout(()=>setReviews(readStorage<ManagedReview[]>(REVIEWS_KEY,defaultReviews)),0);return()=>window.clearTimeout(timer)},[]);
  const commit=(next:ManagedReview[])=>{setReviews(next);saveStorage(REVIEWS_KEY,next)};
  const toggleFeatured=(id:string)=>commit(reviews.map(review=>review.id===id?{...review,featured:!review.featured}:review));
  const remove=(review:ManagedReview)=>{if(window.confirm(`${review.name}님의 리뷰를 삭제할까요? 삭제 후에는 복구할 수 없습니다.`))commit(reviews.filter(item=>item.id!==review.id))};
  const visible=useMemo(()=>reviews.filter(review=>{if(tab==="featured"&&!review.featured)return false;const keyword=query.trim().toLowerCase();return !keyword||[review.className,review.name,review.email,review.phone,review.quote].some(value=>value.toLowerCase().includes(keyword))}),[reviews,tab,query]);
  return <><div className="review-admin-summary"><article><span>전체 리뷰</span><strong>{reviews.length}</strong></article><article><span>평균 평점</span><strong>{reviews.length?(reviews.reduce((sum,review)=>sum+review.rating,0)/reviews.length).toFixed(1):"0.0"} <small>/ 5</small></strong></article><article><span>대표 노출</span><strong className="red">{reviews.filter(review=>review.featured).length}</strong></article><article><span>검색 결과</span><strong>{visible.length}</strong></article></div><section className="admin-panel managed-review-panel"><div className="review-list-toolbar"><div className="review-filter-tabs"><button className={tab==="all"?"active":""} onClick={()=>setTab("all")}>전체</button><button className={tab==="featured"?"active":""} onClick={()=>setTab("featured")}>대표 노출</button><span>총 <strong>{visible.length}개</strong> 리뷰</span></div><div className="review-admin-search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="클래스·이름·이메일·전화번호·리뷰 검색"/></div></div><div className="managed-review-table"><div className="managed-review-head"><span>클래스</span><span>작성자·연락처</span><span>작성일</span><span>평점</span><span>리뷰</span><span>관리</span></div>{visible.map(review=><article key={review.id} className={review.featured?"is-featured":""}><span className="review-product-cell"><b>{review.className}</b>{review.featured&&<em>대표</em>}</span><span className="review-contact-cell"><strong>{review.name}</strong><small>{review.email}</small><small>{review.phone}</small></span><span>{review.date}</span><strong>{review.rating.toFixed(1)}점</strong><p>{review.quote}</p><span className="review-row-actions"><button className={review.featured?"featured":""} onClick={()=>toggleFeatured(review.id)}>{review.featured?"대표 노출중":"대표로 노출"}</button><button className="review-delete" onClick={()=>remove(review)}><Trash2/> 삭제</button></span></article>)}{visible.length===0&&<div className="review-empty-state"><Search/><strong>조건에 맞는 리뷰가 없습니다.</strong></div>}</div></section></>;
}

export function LegacyAdminSettingsManager(){
  const router=useRouter();
  const [tab,setTab]=useState("banner");
  const [banner,setBanner]=useState<BannerData>({eyebrow:"BRANDYACTION EDU · LIVE",title:"감이 아닌 데이터로\n매출 구조를 만드세요.",copy:"4주 실전 클래스 · 8월 19일 개강",link:"/classes/local-marketing"});
  const [saved,setSaved]=useState(false);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState("");
  useEffect(()=>{let active=true;loadAdminBanner().then(data=>{if(active)setBanner(data)}).catch(reason=>{if(active)setError(reason instanceof Error?reason.message:"메인 배너를 불러오지 못했습니다.")});return()=>{active=false}},[]);
  const upload=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file||file.size>1800000)return;setBanner(value=>({...value,image:URL.createObjectURL(file),imageFile:file}));event.target.value=""};
  const save=async()=>{if(saving)return;setSaving(true);setError("");try{await saveAdminBanner(banner);setBanner(await loadAdminBanner());setSaved(true);router.refresh();window.setTimeout(()=>setSaved(false),1800)}catch(reason){setError(reason instanceof Error?reason.message:"메인 배너를 저장하지 못했습니다.")}finally{setSaving(false)}};
  return <div className="settings-layout"><aside><button onClick={()=>setTab("basic")} className={tab==="basic"?"active":""}>기본 정보</button><button onClick={()=>setTab("banner")} className={tab==="banner"?"active":""}>메인 배너</button><button>메뉴·페이지</button><button>결제·환불</button><button>약관·정책</button><button>운영자 권한</button></aside>{tab==="basic"?<section className="admin-panel settings-form"><h2>사이트 기본 정보</h2><p>사이트 기본 정보는 다음 연결 단계에서 관리됩니다.</p><label>사이트명<input defaultValue="브랜디액션 에듀" disabled/></label><label>사이트 설명<textarea defaultValue="사람과 사업의 가능성을 실행으로 바꾸는 실전 교육 플랫폼" disabled/></label><div className="form-two"><label>대표 이메일<input defaultValue="edu@brandyaction.co.kr" disabled/></label><label>고객센터 연락처<input defaultValue="02-1234-5678" disabled/></label></div></section>:<section className="admin-panel banner-editor"><div className="form-card-head"><div><h2>메인 랜딩 배너</h2><p>홈 첫 화면 오른쪽 배너 이미지와 연결 문구를 직접 수정합니다.</p></div><span className="status-label success">DB 연결</span></div><div className={`banner-admin-preview ${banner.image?"has-upload":""}`} style={banner.image?{backgroundImage:`linear-gradient(90deg,rgba(17,17,17,.88),rgba(17,17,17,.15)),url(${banner.image})`}:undefined}><div><span>{banner.eyebrow}</span><strong>{banner.title}</strong><small>{banner.copy}</small></div>{!banner.image&&<b>01</b>}</div><div className="banner-form-grid"><label className="banner-upload"><input type="file" accept="image/png,image/jpeg,image/webp" onChange={upload}/><Upload/><strong>{banner.image?"배너 이미지 변경":"배너 이미지 업로드"}</strong><span>권장 1920 × 960px · JPG, PNG, WEBP · 1.8MB 이하</span></label><div className="admin-field-grid"><label>상단 문구<input value={banner.eyebrow} onChange={e=>setBanner({...banner,eyebrow:e.target.value})}/></label><label>보조 문구<input value={banner.copy} onChange={e=>setBanner({...banner,copy:e.target.value})}/></label><label className="field-full">메인 문구<textarea value={banner.title} onChange={e=>setBanner({...banner,title:e.target.value})}/></label><label className="field-full">연결 URL<input value={banner.link} onChange={e=>setBanner({...banner,link:e.target.value})}/></label></div></div><div className="banner-actions">{banner.image&&<button className="admin-outline" onClick={()=>setBanner({...banner,image:undefined,imageFile:undefined})}><X/> 이미지 삭제</button>}<Link className="admin-outline" href="/"><Eye/> 고객 화면 보기</Link><button className="admin-primary" onClick={save} disabled={saving}><Save/> {saving?"저장 중...":"배너 저장"}</button></div>{error&&<p className="admin-save-error" role="alert">{error}</p>}</section>}<Toast show={saved}>메인 배너가 DB에 저장되었습니다.</Toast></div>;
}
